import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"21. 了解内存布局（堆栈、堆、数据、代码）","description":"The Little Book of C 中文版 — 21. 了解内存布局（堆栈、堆、数据、代码）","frontmatter":{"title":"21. 了解内存布局（堆栈、堆、数据、代码）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","03-内存","中文"],"description":"The Little Book of C 中文版 — 21. 了解内存布局（堆栈、堆、数据、代码）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":21,"sidebarWeight":21,"alternateZh":"/posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code)","alternateEn":"/posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code)"},"headers":[],"relativePath":"posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code).md","filePath":"posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code).md","lastUpdated":1790163617000}'),l={name:"posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code).md"};function p(i,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code))</p><p>在掌握指针或动态内存之前，您需要了解正在运行的 C 程序中内存是如何组织的。 C 为您提供了很少有语言允许的控制级别，但为了安全地使用它，您必须知道数据存放在哪里以及在那里存放多长时间。</p><h4 id="内存段" tabindex="-1">内存段 <a class="header-anchor" href="#内存段" aria-label="Permalink to &quot;内存段&quot;">​</a></h4><p>当程序运行时，其内存分为几个关键部分：</p><table tabindex="0"><thead><tr><th>细分</th><th>目的</th><th>示例数据</th></tr></thead><tbody><tr><td>代码（文本）</td><td>存储编译的机器指令</td><td>函数、程序逻辑</td></tr><tr><td>数据（静态）</td><td>存储具有初始化值的全局变量和静态变量</td><td><code>int count = 5;</code></td></tr><tr><td>BSS（未初始化数据）</td><td>保存从零开始或未初始化的全局/静态变量</td><td><code>int buffer[256];</code></td></tr><tr><td>堆</td><td>用于动态内存分配（<code>malloc</code>,<code>calloc</code>)</td><td>运行时创建的大型数据</td></tr><tr><td>堆栈</td><td>存储局部变量、函数参数、返回地址</td><td>函数调用、递归</td></tr></tbody></table><p>这些段由操作系统以不同的方式管理，并且每个段都有不同的生命周期和范围。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是一个小程序，它打印不同变量的内存地址以显示它们所在的位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>// Global variable (Data segment)</span></span>
<span class="line"><span>int global_var = 42;</span></span>
<span class="line"><span>// Uninitialized global variable (BSS segment)</span></span>
<span class="line"><span>int global_bss;</span></span>
<span class="line"><span>void show_addresses(void) {</span></span>
<span class="line"><span>    // Local variable (Stack)</span></span>
<span class="line"><span>    int local_var = 10;</span></span>
<span class="line"><span>    // Static variable (Data segment)</span></span>
<span class="line"><span>    static int static_var = 20;</span></span>
<span class="line"><span>    // Dynamic variable (Heap)</span></span>
<span class="line"><span>    int *heap_var = malloc(sizeof(int));</span></span>
<span class="line"><span>    *heap_var = 30;</span></span>
<span class="line"><span>    printf(&quot;Code (function) address:     %p\\n&quot;, (void *)show_addresses);</span></span>
<span class="line"><span>    printf(&quot;Global variable address:     %p\\n&quot;, (void *)&amp;global_var);</span></span>
<span class="line"><span>    printf(&quot;Uninitialized global address:%p\\n&quot;, (void *)&amp;global_bss);</span></span>
<span class="line"><span>    printf(&quot;Static variable address:     %p\\n&quot;, (void *)&amp;static_var);</span></span>
<span class="line"><span>    printf(&quot;Stack variable address:      %p\\n&quot;, (void *)&amp;local_var);</span></span>
<span class="line"><span>    printf(&quot;Heap variable address:       %p\\n&quot;, (void *)heap_var);</span></span>
<span class="line"><span>    free(heap_var);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    show_addresses();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc memory_layout.c -o memory_layout</span></span>
<span class="line"><span>./memory_layout</span></span></code></pre></div><p>示例输出（地址因系统而异）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Code (function) address:     0x561ce7348169</span></span>
<span class="line"><span>Global variable address:     0x561ce7546014</span></span>
<span class="line"><span>Uninitialized global address:0x561ce7546018</span></span>
<span class="line"><span>Static variable address:     0x561ce7546020</span></span>
<span class="line"><span>Stack variable address:      0x7ffc94b65a5c</span></span>
<span class="line"><span>Heap variable address:       0x561ce774b2a0</span></span></code></pre></div><p>注意栈地址远高于堆，栈通常向下增长，而堆在内存中向上增长。</p><h4 id="一切如何运作" tabindex="-1">一切如何运作 <a class="header-anchor" href="#一切如何运作" aria-label="Permalink to &quot;一切如何运作&quot;">​</a></h4><p>代码段</p><ul><li>包含编译指令。</li><li>通常标记为只读以防止意外修改。</li></ul><p>数据段</p><ul><li>保存用值初始化的全局变量和静态变量。</li><li>在整个计划期间都存在。</li></ul><p>BSS（由符号开始的块）</p><ul><li>保存未初始化的全局/静态变量。</li><li>运行时自动零初始化。</li></ul><p>堆</p><ul><li>用于局部变量和函数调用。</li><li>随着函数被调用和返回而自动管理、增长和收缩。</li></ul><p>堆</p><ul><li>在运行时手动分配。</li><li>需要明确的管理（<code>malloc</code>和<code>free</code>).</li></ul><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>每次编写变量时，无论是否有意识，您都在决定它在内存中的位置。了解此布局可以帮助您：</p><ul><li>调试内存错误（分段错误、泄漏、损坏）。</li><li>关于性能和函数调用的原因。</li><li>使用时编写正确的代码<code>malloc</code>,<code>free</code>和指针。</li><li>构建真实的系统软件，如分配器或内核。</li></ul><p>如果没有这种思维模型，C 内存错误就会让人感到神秘；有了它，它们就变得合乎逻辑并且可以修复。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>在示例中添加更多全局、局部和静态变量并打印它们的地址。</li><li>分配两个块<code>malloc()</code>并比较它们的地址，堆向上增长。</li><li>打电话<code>show_addresses()</code>多次并注意每次调用时堆栈变量的地址如何变化。</li><li>将变量从全局移动到局部，并观察其内存段如何变化。</li><li>绘制一个图表，显示系统的堆栈、堆、数据和代码区域。</li></ol><p>了解内存布局是您进入系统级 C 语言的第一步，您可以通过它开始将代码不仅视为文本，而且视为内存中的结构化字节。</p>`,32)])])}const b=s(l,[["render",p]]);export{u as __pageData,b as default};
